# Signed netting, frozen collateral units and joint default/exposure loss.
if(!exists('counterparty_exposure_backtest'))library(creditratingsystem)
run_counterparty_credit_products<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/counterparty_credit_products.json',package='creditratingsystem'),simplifyVector=FALSE);out<-errors<-list()
 for(name in names(data$variants)){
 case<-data$variants[[name]];route<-do.call(route_rating_profile,case$route_input)$value;pd<-predict_pd(case$model,matrix(0,1,1),feature_order='x',expected_target=case$model$target)$value;net<-do.call(aggregate_netting_set_exposure,case$netting_input)$value;args<-case$margin_input;args$netting_paths<-net;collateral<-do.call(simulate_collateral_margin,args)$value;closeargs<-list(freeze_timing='BEFORE_DATE_EVENTS',cashflow_convention='UNSETTLED_EXCLUDED_FROM_CLOSEOUT_VALUE');closed<-do.call(closeout_exposure_at_default,c(list(netting_paths=net,collateral_paths=collateral,default_events=case$default_events,intermediate_cashflows=case$intermediate_cashflows),closeargs))$value;exposure<-matrix(vapply(closed$closeouts,function(r)r$closeout_exposure,numeric(1)),ncol=1);lossargs<-list(default_indicator=matrix(c(1,0),ncol=1),net_exposure_paths=exposure,recovery_paths=matrix(.4,2,1),scenario_weights=c(.5,.5),discount_factors=matrix(1,2,1),counterparty_id='cp',netting_set_id='n',scenario_ids=c('h','l'),time_grid=2/365,currency='EUR',probability_measure='PHYSICAL');loss<-do.call(counterparty_expected_loss,lossargs)$value
 actual_inputs<-case$netting_input;for(key in c('trade_value_paths','fx_paths'))actual_inputs[[key]]<-Filter(function(r)r$path_id=='h',actual_inputs[[key]]);actual<-do.call(aggregate_netting_set_exposure,actual_inputs)$value;am<-case$margin_input;for(key in c('call_calendar','collateral_market_paths'))am[[key]]<-Filter(function(r)r$path_id=='h',am[[key]]);am$netting_paths<-actual;actual_coll<-do.call(simulate_collateral_margin,am)$value;forecast<-case$forecast;observation<-case$observation;forecast$netting_paths<-net;observation$netting_paths<-actual
 if(name=='collateralized'){forecast<-c(forecast,list(collateral_paths=collateral,csa_version='1',default_events=list(case$default_events[[1]]),intermediate_cashflows=list(case$intermediate_cashflows[[1]])),closeargs,list(default_sampling_contract=list(mode='JOINT_SIMULATED_PATHS',known_at='2024-01-01',reference='synthetic-joint-default-paths')));observation<-c(observation,list(collateral_paths=actual_coll,csa_version='1',closeout_event=case$default_events[[1]],intermediate_cashflows=list(case$intermediate_cashflows[[1]]),reported_closeout_exposure=80,closeout_known_at='2024-01-04'))}
 validation<-counterparty_exposure_backtest(list(forecast),list(observation),quantile_levels=c(.5,.95),design=case$validation_design,uncertainty='none')$value;subject<-list(subject_id=paste0(name,'-netting'),subject_type='transaction');components<-list(c(list(component_id=paste0(name,'-el'),quantity='EL',value=loss$expected_loss,currency='EUR'),subject,list(variant='joint_default_exposure',definition=case$model$target)));binding<-list(profile_id=route$profile_id,profile_version='1',model_id='ccr-reference',model_version='v1',model_hash=collateral$artifact_hash,input_hash=net$artifact_hash);assessment<-compose_risk_assessment(paste0(name,'-assessment'),subject,components,binding,'2024-01-01','2024-01-01','2024-01-01')$value;separate<-do.call(aggregate_netting_set_exposure,case$separate_netting_input)$value
 error<-tryCatch({if(name=='netting_set'){wrong<-case$netting_input;wrong$netting_agreements[[1]]$legally_enforceable<-FALSE;do.call(aggregate_netting_set_exposure,wrong)}else if(name=='collateralized'){wrong<-case$default_events;wrong[[1]]$closeout_date<-'2024-01-04';do.call(closeout_exposure_at_default,c(list(netting_paths=net,collateral_paths=collateral,default_events=wrong,intermediate_cashflows=case$intermediate_cashflows),closeargs))}else if(name=='uncollateralized'){wrong<-case$netting_input;extra<-wrong$netting_agreements[[1]];extra$netting_set_id<-'duplicate';wrong$netting_agreements<-c(wrong$netting_agreements,list(extra));do.call(aggregate_netting_set_exposure,wrong)}else{lossargs$scenario_ids<-c('h','h');do.call(counterparty_expected_loss,lossargs)}},error=identity);stopifnot(inherits(error,'creditratingsystem_error'));errors[[name]]<-error$code;out[[name]]<-list(route=route,pd=as.list(pd),netting=net,collateral=collateral,closeout=closed,loss=loss,validation=validation,assessment=assessment,separate_sets=separate)
 }
 if(verify_reference){same<-function(a,b)stopifnot(is.finite(a),abs(a-b)<=1e-10+1e-12*abs(b));for(name in names(out)){r<-out[[name]];same(r$pd[[1]],.5);same(r$loss$expected_loss,if(name=='collateralized')24 else 27);same(r$netting$paths[[1]]$positive_exposure,40);same(sum(vapply(Filter(function(x)x$date=='2024-01-01',r$separate_sets$paths),function(x)x$positive_exposure,numeric(1))),100);stopifnot(r$assessment$composition_status=='CONSISTENT',length(r$validation$diagnostics$reconciliation_violations)==0)};same(out$wrong_way$loss$independent_default_exposure_loss,15);same(out$wrong_way$loss$default_exposure_dependence_contribution,12);x<-out$collateralized;same(x$closeout$closeouts[[1]]$closeout_exposure,80);same(x$validation$metrics$market_exposure$mean_outcome,0);same(x$validation$metrics$conditional_default_closeout$mean_outcome,80);stopifnot(identical(errors,list(netting_set='NETTING_ELIGIBILITY',collateralized='INSUFFICIENT_PATH_EXTENSION',uncollateralized='NETTING_OVERLAP',wrong_way='INVALID_IDENTIFIERS')))}
 list(data_origin=data$data_origin,version=data$version,product=data$product,variants=out,contract_error_codes=errors)
}
